///
/// \file    sentinel_task_rtc_service.hpp
/// \brief   DS3231 RTC service task (1 Hz SQW-interrupt driven)
///
/// \details This header declares the RTC service FreeRTOS task. The task
///          programmes the DS3231 to emit a 1 Hz square wave on its INT/SQW
///          pin, takes that signal as a falling-edge GPIO interrupt on
///          \ref sentinel::resource::rtc_sqw_pin, and on each edge latches
///          the current time from the RTC over the arbitrated I²C bus.
///
///          The square-wave edge is generated by the same TCXO that
///          increments the DS3231's seconds register, so each interrupt is
///          phase-aligned to the real second rollover — the latched time is
///          always fresh rather than sampled at an arbitrary offset. The
///          interrupt also lets the MCU sleep between ticks instead of
///          polling the bus.
///
///          The most recent timestamp is published via
///          \ref sentinel::task::rtc_service::last_unix_time for other tasks to
///          consume (e.g. a future BLE Current Time characteristic). This task
///          does not set the RTC; initial/authoritative time-setting belongs to
///          the BLE sync path.
///
/// \author  galudino
/// \date    2026-05-24
/// \version 1.0 - Initial RTC service task
///

#ifndef SENTINEL_TASK_RTC_SERVICE_HPP
#define SENTINEL_TASK_RTC_SERVICE_HPP

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wpedantic"
extern "C" {
#include <FreeRTOS.h>
#include <cyhal_gpio.h>
#include <task.h>
}
#pragma GCC diagnostic pop

#include <cstdint>

namespace sentinel::task {

///
/// \brief Single-owner FreeRTOS task that latches the DS3231 time on each
///        1 Hz SQW-interrupt tick and publishes it for cross-task consumers.
///
/// \details OO/class style, mirroring \ref sentinel::task::spi_bus — the task's
///          state (latched time/temperature, the SQW callback registration,
///          the bus transport, the task handle) lives in private members rather
///          than \c .cpp file-static globals, and the loop runs as a private
///          \ref run reached via a static trampoline. The SQW ISR is a private
///          static member reached via the instance pointer carried in the
///          callback data, so the object must have a stable address. Use the
///          \ref instance singleton.
///
/// \note    This class is non-copyable and non-movable.
///
class rtc_service {
public:
    ///
    /// \brief The single RTC-service instance.
    ///
    /// \return Reference to the singleton \ref rtc_service instance.
    ///
    static rtc_service &instance() noexcept;

    /// Non-copyable, non-movable: the task/ISR entry points capture \c this.
    rtc_service(const rtc_service &) = delete;
    rtc_service &operator=(const rtc_service &) = delete;
    rtc_service(rtc_service &&) = delete;
    rtc_service &operator=(rtc_service &&) = delete;

    ///
    /// \brief Create and start the RTC service task.
    ///
    /// \return \c pdPASS if the task was created successfully, otherwise the
    ///         \c xTaskCreate failure code.
    ///
    BaseType_t task_create() noexcept;

    ///
    /// \brief Seed the latched time with one synchronous DS3231 read (#74).
    ///
    /// \details Called once by the boot orchestrator right after the device
    ///          context is built — before POST, the boot-lifecycle event
    ///          records, and the first snapshot — so those carry the real
    ///          battery-backed time instead of epoch 0. The task (started
    ///          later) then keeps the latch fresh at 1 Hz. Must not be called
    ///          once the task is running (the task is the latch's sole writer
    ///          from then on).
    ///
    ///          #94: if the DS3231's oscillator-stop flag (OSF) is set, the
    ///          chip lost power without a working backup battery and restarted
    ///          at its 2000-01-01 default — its time is \e not trusted. The
    ///          latch then stays 0 ("time unknown") until a BLE time-set
    ///          (\ref time_set_from_ble) supplies a real time.
    ///
    /// \return \c true if the DS3231 was read (see \ref time_valid for
    ///         whether its time was trusted); \c false if the read failed
    ///         (the latch stays 0 — boot continues and records are stamped 0).
    ///
    bool seed_time() noexcept;

    ///
    /// \brief Is the latched time real (#94)?
    ///
    /// \return \c false while the DS3231 reports a lost-power oscillator stop
    ///         and no time has been set since; \ref last_unix_time is then 0.
    ///
    bool time_valid() const noexcept;

    ///
    /// \brief Record a BLE time-set (#94): the DS3231 now holds a real time.
    ///
    /// \details Called by the Unix Time write handler after it programs the
    ///          DS3231. Clears the oscillator-stop flag, marks the time valid
    ///          and latches \p unix_seconds immediately, so records written
    ///          before the next 1 Hz tick are already stamped correctly.
    ///
    /// \param unix_seconds The time just written to the DS3231.
    ///
    void time_set_from_ble(uint32_t unix_seconds) noexcept;

    ///
    /// \brief Most recent Unix timestamp latched on a 1 Hz SQW tick.
    ///
    /// \return Seconds since 1970-01-01 UTC as of the last tick (or the boot
    ///         \ref seed_time), or \c 0 before either (or if the RTC time was
    ///         unreadable). Backed by a
    ///         32-bit aligned value, so the read is atomic on Cortex-M without
    ///         a lock.
    ///
    uint32_t last_unix_time() const noexcept;

    ///
    /// \brief Most recent DS3231 die temperature, in 0.01 °C.
    ///
    /// \details Cached on the same cadence the time is latched. Consumed by the
    ///          device snapshot \c populate() (#36) so it never has to issue a
    ///          fresh I²C read of its own. Backed by a 16-bit aligned value, so
    ///          the cross-task read is atomic on Cortex-M without a lock.
    ///
    /// \return Temperature in 0.01 °C as of the last successful read, or \c 0
    ///         before the first successful read.
    ///
    int16_t last_temperature_centi_c() const noexcept;

    ///
    /// \brief Has \ref last_temperature_centi_c been populated by a real read?
    ///
    /// \details \c false from boot until the first successful DS3231
    ///          temperature read, which now happens on the first SQW tick
    ///          rather than at the first logging boundary (#89). Lets the boot
    ///          snapshot wait for a real value instead of persisting 0.00 °C.
    ///
    /// \return \c true once a temperature has been read since boot.
    ///
    bool has_temperature() const noexcept;

private:
    rtc_service() = default;

    /// \brief Static FreeRTOS task entry point; forwards to \ref run.
    /// \param task_parameter Unused (\c this is captured via \ref instance).
    static void task_trampoline(void *task_parameter);

    /// \brief SQW falling-edge GPIO ISR; latches the time/temperature.
    /// \param callback_arg Unused (\c this is recovered via \ref instance).
    /// \param event        GPIO event that fired (unused; any edge latches).
    static void sqw_event_isr(void *callback_arg, cyhal_gpio_event_t event);

    ///
    /// \brief RTC service loop. Configures the 1 Hz SQW interrupt, then latches
    ///        the current time on every tick.
    ///
    void run();

    /// \brief Register the SQW falling-edge callback and enable the interrupt
    ///        on \ref sentinel::resource::rtc_sqw_pin.
    void configure_sqw_interrupt() noexcept;

    cyhal_gpio_callback_data_t m_sqw_callback_data{}; ///< Persistent SQW reg.

    /// Last Unix timestamp latched on a tick. 32-bit aligned → atomic
    /// single-word access on Cortex-M, so no lock is needed for the cross-task
    /// read in \ref last_unix_time.
    volatile uint32_t m_last_unix_seconds{0};

    /// Last DS3231 die temperature in 0.01 °C. 16-bit aligned → atomic
    /// single-halfword access on Cortex-M, so no lock is needed for the read in
    /// \ref last_temperature_centi_c.
    volatile int16_t m_last_temperature_centi{0};

    /// \c true once \ref m_last_temperature_centi holds a real reading (#89).
    volatile bool m_temperature_known{false};

    /// \c false while the DS3231 time is untrusted after an oscillator stop
    /// (#94); the tick then leaves \ref m_last_unix_seconds at 0.
    volatile bool m_time_valid{true};

    TaskHandle_t m_handle{nullptr}; ///< FreeRTOS task handle.
};

} // namespace sentinel::task

#endif /* SENTINEL_TASK_RTC_SERVICE_HPP */
